// Merge all data sources into one object
const prs = $input.all()[0]?.json || [];
const issues = $input.all()[1]?.json || [];
const commits = $input.all()[2]?.json || [];
const releases = $input.all()[3]?.json || [];

const repo = $json.repo;

// Filter PRs merged in last 7 days
const mergedPRs = Array.isArray(prs) ? prs.filter(pr =>
  pr.merged_at && new Date(pr.merged_at) > new Date(Date.now() - 7 * 24 * 60 * 60 * 1000)
) : [];

// Filter issues from last 7 days
const recentIssues = Array.isArray(issues) ? issues.filter(issue =>
  new Date(issue.closed_at || issue.updated_at) > new Date(Date.now() - 7 * 24 * 60 * 60 * 1000)
) : [];

// Filter commits from last 7 days
const recentCommits = Array.isArray(commits) ? commits.filter(c =>
  new Date(c.commit.author.date) > new Date(Date.now() - 7 * 24 * 60 * 60 * 1000)
) : [];

// Get releases
const recentReleases = Array.isArray(releases) ? releases.slice(0, 5) : [];

return {
  repo,
  week_ending: new Date().toISOString().split('T')[0],
  stats: {
    merged_prs: mergedPRs.length,
    closed_issues: recentIssues.length,
    commits: recentCommits.length,
    releases: recentReleases.length,
  },
  merged_prs: mergedPRs.map(pr => ({
    title: pr.title,
    author: pr.user?.login,
    url: pr.html_url,
    merged_at: pr.merged_at,
  })),
  closed_issues: recentIssues.map(issue => ({
    title: issue.title,
    url: issue.html_url,
    labels: issue.labels?.map(l => l.name) || [],
  })),
  recent_commits: recentCommits.slice(0, 5).map(c => ({
    message: c.commit.message.split('\n')[0],
    author: c.commit.author.name,
    url: c.html_url,
  })),
  releases: recentReleases.map(r => ({
    name: r.name || r.tag_name,
    url: r.html_url,
    published_at: r.published_at,
  })),
};

