// Parse Claude API response
const response = $json;
let summary = '';

if (response.content && Array.isArray(response.content)) {
  // Anthropic format
  summary = response.content
    .filter(c => c.type === 'text')
    .map(c => c.text)
    .join('\n');
} else if (response.choices) {
  // OpenAI format fallback
  summary = response.choices[0]?.message?.content || '';
} else if (typeof response === 'string') {
  summary = response;
}

return {
  repo: $json.repo,
  week_ending: $json.week_ending,
  summary: summary || 'No summary generated',
  word_count: (summary || '').split(' ').length,
  generated_at: new Date().toISOString(),
};

// Format the final markdown document
const summary = $json.summary;
const repo = $json.repo;
const weekEnding = $json.week_ending;

const markdown = [
  '# Weekly Dev Summary: ' + repo,
  '',
  '**Week ending:** ' + weekEnding + '  |  **Generated:** ' + new Date().toLocaleString(),
  '',
  '---',
  '',
  summary,
  '',
  '---',
  '',
  '*Generated by n8n workflow using Claude AI*'
].join('\n');

return {
  repo: repo,
  week_ending: weekEnding,
  markdown_summary: markdown,
  generated_at: $json.generated_at,
};

// Save summary info
const repo = $json.repo.replace('/', '-');
const date = $json.week_ending;

return {
  repo: $json.repo,
  date: $json.week_ending,
  markdown: $json.markdown_summary,
  file: 'weekly-summaries/' + repo + '-' + date + '.md',
  word_count: $json.markdown_summary.split(' ').length,
};
